def fibonacci(n):
    """Calculates the nth Fibonacci number."""
    if n <= 0:
        return 0
    elif n == 1 or n == 2:
        return 1

    a, b = 1, 1
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

def is_prime(n):
    """Checks if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_of_first_n_primes(n):
    """Calculates the sum of the first n prime numbers."""
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return sum(primes)

if __name__ == "__main__":
    # Calculate the 25th Fibonacci number
    fib_25 = fibonacci(25)

    # Calculate the sum of the first 100 prime numbers
    sum_primes_100 = sum_of_first_n_primes(100)

    print(f"The 25th Fibonacci number is: {fib_25}")
    print(f"The sum of the first 100 prime numbers is: {sum_primes_100}")
